INSERT INTO public.nhia_tariff_items (
  tariff_version, facility_group, catering_option, mdc, gdrg_code, description,
  age_band, tariff_amount, currency, source_file, source_page, is_active, updated_at
)
SELECT
  tariff_version, facility_group, catering_option, mdc, gdrg_code, description,
  age_band, tariff_amount, currency, source_file, source_page, is_active, NOW()
FROM seed_rows
ON CONFLICT (tariff_version, facility_group, catering_option, gdrg_code) DO UPDATE SET
  mdc = EXCLUDED.mdc,
  description = EXCLUDED.description,
  age_band = EXCLUDED.age_band,
  tariff_amount = EXCLUDED.tariff_amount,
  currency = EXCLUDED.currency,
  source_file = EXCLUDED.source_file,
  source_page = EXCLUDED.source_page,
  is_active = EXCLUDED.is_active,
  updated_at = NOW();

DO $$
DECLARE
  seeded_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO seeded_count
  FROM public.nhia_tariff_items
  WHERE tariff_version = 'FEB 2023'
    AND facility_group = 'Private Primary Care Hospital'
    AND catering_option = 'exclusive';

  IF seeded_count <> 617 THEN
    RAISE EXCEPTION 'Expected 617 Private Primary Care Hospital exclusive tariff rows, found %', seeded_count;
  END IF;
END $$;

COMMIT;
